'use strict';
const trainer=new EvolutionTrainer(),trainCanvas=$('training'),trainCtx=trainCanvas.getContext('2d');
let activeLab='steering',trainerUI=0;
const concepts=[
['Agents et vecteurs','Vehicle porte position, vitesse et accélération. Les sous-classes sélectionnent les actions et BehaviorManager pondère les forces.','9–16'],
['Seek / Flee','Les poissons peuvent viser le requin ou fuir sa position. Flee inverse la vitesse désirée, pas la force déjà calculée.','14–18'],
['Pursue / Evade','Les requins rouges anticipent la cible. Les proies prédisent le déplacement du prédateur avant de fuir.','19–21'],
['Arrive','Le requin freine près du pointeur. Une distance d’arrêt maintient les suiveurs à distance de leur cible.','22–25'],
['Wander','Une direction varie progressivement sur un cercle devant l’agent : pas de nouvelle direction aléatoire à chaque image.','26–28'],
['Projection scalaire','Le produit scalaire projette la position future sur chaque segment. Le segment le plus proche fournit une cible avancée.','29–31'],
['Path following','Le mode Migration suit un circuit fermé, avec anticipation du segment suivant et évitement permanent des rochers.','30–31'],
['Avoid / Boundaries','Un regard devant dont la longueur dépend de la vitesse, un regard court et la position préviennent les collisions. Les limites repoussent les agents.','32–36, 61'],
['Boids','Séparation, alignement et cohésion forment les bancs. Leurs poids se règlent séparément.','37–42'],
['Évolution génétique','Vie, nourriture et poison influencent la survie. Les survivants en meilleure santé engendrent une descendance à ADN muté.','43–46'],
['Neuro-évolution','Le laboratoire entraîne de vrais réseaux : sélection par fitness, élites, croisement et mutation des poids et biais.','47–49, 53–54'],
['Suivi de leader','Arrive derrière le requin + séparation. Un suiveur devant le leader fuit le point projeté pour dégager sa trajectoire.','50–51, 61–62'],
['Snake / formations','Le mode Snake fait arriver chaque poisson sur le précédent. L’escorte applique le suivi de leader non naïf.','23, 58, 61–62'],
['BehaviorManager','Chaque agent possède ses comportements nommés, activables, supprimables, pondérables et sérialisables.','52, 60'],
['Machine learning','Le modèle pré-entraîné HandPose de ml5 peut contrôler le requin avec la main. Distinct des agents réactifs et du réseau évolutif.','48, 55']
];
$('conceptList').innerHTML=concepts.map(([name,description,slides])=>`<div class="concept-row"><b>${name}</b><span>${description}</span><small>Slides ${slides}</small></div>`).join('');
document.querySelectorAll('[data-lab]').forEach(button=>button.onclick=()=>{activeLab=button.dataset.lab;document.querySelectorAll('[data-lab]').forEach(b=>b.classList.toggle('selected',b===button));for(const id of ['steering','evolution','concepts'])show(`pane-${id}`,id===activeLab);if(activeLab==='evolution')renderTraining();});
const paramsMap={maxSpeed:'speedOut',maxForce:'forceOut',vision:'visionOut',prediction:'predictionOut',population:'populationOut',separation:'separationOut',alignment:'alignmentOut',cohesion:'cohesionOut'};
for(const [id,out]of Object.entries(paramsMap)){$(id).oninput=()=>{game.params[id]=Number($(id).value);$(out).textContent=$(id).value;if(id==='population'){while(game.fish.length<game.params.population){const p=safePosition();game.fish.push(new Fish(p.x,p.y,Math.floor(rand(0,3))));}if(game.fish.length>game.params.population)game.fish.length=game.params.population;}};}
for(const id of ['currents','genetic','trails','vectors'])$(id).onchange=()=>game.params[id]=$(id).checked;
$('behavior').onchange=()=>setMode($('behavior').value);
$('backExplore').onclick=()=>{const mode=game.mode;if(game.state==='menu'||game.state==='ended')start(true);setMode(mode);closeDialog('lab');if(game.state==='paused'){game.state='playing';show('pauseScreen',false);}};
$('saveConfig').onclick=()=>{try{localStorage.setItem('abyss-config',JSON.stringify({version:1,params:game.params,mode:game.mode,manager:game.player.manager.serialize()}));toast('Réglages sauvegardés sur cet appareil');}catch{toast('Stockage indisponible dans ce navigateur');}};
$('loadConfig').onclick=()=>{try{const data=JSON.parse(localStorage.getItem('abyss-config'));if(!data||data.version!==1)throw Error();for(const[id,out]of Object.entries(paramsMap)){const v=data.params[id];if(Number.isFinite(v)){const input=$(id);input.value=String(clamp(v,Number(input.min),Number(input.max)));input.oninput();}}for(const id of ['currents','genetic','trails','vectors']){$(id).checked=!!data.params[id];$(id).onchange();}if(['flock','wander','path','leader','snake','seek','flee','evade'].includes(data.mode))setMode(data.mode);if(Array.isArray(data.manager))game.player.manager.restore(data.manager);toast('Réglages restaurés');}catch{toast('Aucun réglage valide à restaurer');}};
const topologyMap={nnPop:'population',nnRays:'rays',nnLayers:'layers',nnHidden:'hidden',nnMutation:'mutation'};
for(const[id,key]of Object.entries(topologyMap)){$(id).oninput=()=>{$(id).parentElement.querySelector('output').textContent=$(id).value;trainer.cfg[key]=Number($(id).value);if(key!=='mutation'){trainer.testing=false;trainer.createWorld();trainer.reset();renderTraining();updateTrainingUI();}};}
$('nnActivation').onchange=()=>{trainer.cfg.activation=$('nnActivation').value;trainer.testing=false;trainer.reset();renderTraining();updateTrainingUI();};
$('trainBtn').onclick=()=>{trainer.running=!trainer.running;trainer.reason=trainer.running?(trainer.testing?'Test de généralisation':'Sélection naturelle en cours'):'En pause';updateTrainingUI();};
$('trainReset').onclick=()=>{trainer.testing=false;trainer.createWorld();trainer.reset();updateTrainingUI();renderTraining();};
function downloadJSON(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('saveBrain').onclick=()=>{downloadJSON(trainer.exportBrain().toJSON(),'abyss-cerveau.json');trainer.reason='Cerveau exporté';updateTrainingUI();};
$('loadBrain').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Fichier trop volumineux.');const data=JSON.parse(await file.text()),brain=Brain.fromJSON(data);trainer.cfg.rays=brain.shape[0]-6;trainer.cfg.layers=brain.shape.length-2;trainer.cfg.hidden=brain.shape[1];trainer.cfg.activation=brain.activation;for(const[id,key]of Object.entries(topologyMap)){if(key==='population'||key==='mutation')continue;$(id).value=trainer.cfg[key];$(id).parentElement.querySelector('output').textContent=trainer.cfg[key];}$('nnActivation').value=brain.activation;trainer.bestEver=brain;trainer.bestFitness=0;trainer.elapsed=0;trainer.generation=1;trainer.agents=Array.from({length:trainer.cfg.population},()=>new TrainingAgent(90,180,brain.clone()));trainer.running=false;trainer.testing=false;trainer.reason='Cerveau importé · prêt à tester';updateTrainingUI();renderTraining();}catch(error){trainer.reason='Import refusé : '+error.message;updateTrainingUI();}e.target.value='';};
$('testBrain').onclick=()=>{trainer.testNewWorld();updateTrainingUI();};
function updateTrainingUI(){const best=trainer.best();$('generation').textContent=`${trainer.testing?'TEST':'GÉNÉRATION'} ${trainer.generation}`;$('fitness').textContent=Math.round(Math.max(trainer.bestFitness,best?.score||0));$('trainFood').textContent=best?.catches||0;$('trainProgress').textContent=Math.min(100,Math.floor(trainer.elapsed/12*100))+'%';$('trainState').textContent=trainer.reason;$('trainBtn').textContent=trainer.running?'Mettre en pause':'Lancer l’entraînement';}
function renderTraining(){const c=trainCtx,w=trainer.w,h=trainer.h;c.fillStyle='#05202e';c.fillRect(0,0,w,h);for(let x=0;x<w;x+=45){c.strokeStyle='#ffffff04';c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(const o of trainer.obstacles){c.beginPath();c.arc(o.pos.x,o.pos.y,o.radius,0,Math.PI*2);c.fillStyle='#254959';c.fill();c.strokeStyle='#61919455';c.stroke();}for(let i=0;i<trainer.food.length;i++){const p=trainer.food[i];c.beginPath();c.arc(p.x,p.y,8,0,Math.PI*2);c.fillStyle='#e5c68d';c.fill();c.font='10px monospace';c.fillStyle='#c0d4d1';c.fillText(String(i+1),p.x-3,p.y-15);}const best=trainer.best();for(const a of trainer.agents){if(a===best)continue;c.save();c.translate(a.pos.x,a.pos.y);c.rotate(a.vel.heading());c.beginPath();c.moveTo(10,0);c.lineTo(-7,-4);c.lineTo(-5,0);c.lineTo(-7,4);c.closePath();c.fillStyle='#70b5c64a';c.fill();c.restore();}if(best){c.strokeStyle='#7de6ce66';c.lineWidth=1;c.beginPath();best.history.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();c.save();c.translate(best.pos.x,best.pos.y);c.rotate(best.vel.heading());c.beginPath();c.moveTo(15,0);c.lineTo(-9,-7);c.lineTo(-5,0);c.lineTo(-9,7);c.closePath();c.fillStyle='#7de6ce';c.fill();c.restore();const target=trainer.food[best.targetIndex%trainer.food.length];c.setLineDash([3,5]);c.beginPath();c.moveTo(best.pos.x,best.pos.y);c.lineTo(target.x,target.y);c.strokeStyle='#e5c68d33';c.stroke();c.setLineDash([]);const rays=best.brain.shape[0]-6;for(let i=0;i<rays;i++){const dir=Vec.fromAngle(best.vel.heading()+(i/(rays-1)-.5)*Math.PI);c.beginPath();c.moveTo(best.pos.x,best.pos.y);c.lineTo(best.pos.x+dir.x*90,best.pos.y+dir.y*90);c.strokeStyle='#7de6ce16';c.stroke();}}c.fillStyle='#769eab';c.font='10px monospace';c.fillText('RÉSEAU '+trainer.shape().join(' → ')+'  ·  '+trainer.cfg.activation.toUpperCase(),18,24);c.fillText('● AGENT LE PLUS PERFORMANT',18,h-17);}
function tickTrainer(dt){if(!$('lab').open||activeLab!=='evolution')return;if(trainer.testing&&trainer.running){trainer.elapsed+=dt*2;for(const a of trainer.agents)a.step(dt*2,trainer);if(trainer.elapsed>=12){trainer.running=false;trainer.reason=`Test terminé : ${trainer.best().catches} capture(s). La généralisation n’est pas garantie.`;}}else{ // Pas fixe pour que la fitness ne dépende pas du nombre d'images.
trainerUI+=Math.min(dt,.05);while(trainerUI>=1/60){trainer.step(1/60);trainerUI-=1/60;}}
renderTraining();updateTrainingUI();}
// Caméra facultative. Aucun accès tant que le bouton n'est pas pressé.
let handModel=null,cameraStream=null,cameraStarting=false,cameraEpoch=0;
function loadML5(){if(window.ml5)return Promise.resolve();return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/ml5@1.3.1/dist/ml5.min.js';script.onload=resolve;script.onerror=()=>reject(Error('La bibliothèque ml5 est inaccessible. Vérifie Internet.'));document.head.append(script);});}
function stopCamera(){cameraEpoch++;if(handModel?.detectStop)handModel.detectStop();if(cameraStream)cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null;$('camera').srcObject=null;cameraStarting=false;$('cameraStatus').textContent='Caméra arrêtée.';$('cameraBtn').disabled=false;}
$('cameraStop').onclick=stopCamera;
$('cameraBtn').onclick=async()=>{if(cameraStarting||cameraStream)return;cameraStarting=true;const epoch=++cameraEpoch;$('cameraBtn').disabled=true;$('cameraStatus').textContent='Chargement de ml5 et du modèle HandPose…';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Utilise HTTPS ou localhost avec une webcam.');await loadML5();if(epoch!==cameraEpoch)return;handModel=await window.ml5.handPose({maxHands:1});if(epoch!==cameraEpoch)return;const stream=await navigator.mediaDevices.getUserMedia({video:{width:640,height:480},audio:false});if(epoch!==cameraEpoch){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;const video=$('camera');video.srcObject=stream;await video.play();handModel.detectStart(video,hands=>{if(!cameraStream)return;if(hands.length){const p=hands[0].index_finger_tip||hands[0].keypoints?.[8];if(p){game.target=screenToWorld(new Vec((1-p.x/(video.videoWidth||640))*game.width,p.y/(video.videoHeight||480)*game.height));}}});$('cameraStatus').textContent='Contrôle actif · ferme le laboratoire et dirige ton index. Le bouton Arrêter coupe la caméra.';}catch(error){stopCamera();$('cameraStatus').textContent=error.message||'Impossible d’activer la caméra.';}finally{cameraStarting=false;if(!cameraStream)$('cameraBtn').disabled=false;}};
window.addEventListener('pagehide',stopCamera);
